$escaped   = array_map(fn($e) => "'" . addslashes($e) . "'", $emails);
$in_list   = implode(',', $escaped);
$inserts   = [];
foreach (array_chunk($escaped, 2000) as $chunk) {
    $values    = implode(",\n", array_map(fn($e) => "({$e}, 'Imported from users_export_email.xlsx', UNIX_TIMESTAMP())", $chunk));
    $inserts[] = "INSERT IGNORE INTO `captcha_bypass` (`email`, `comment`, `created`) VALUES\n{$values}";
}

return [
    'description' => 'Populate captcha_bypass with 14571 email addresses imported from users_export_email.xlsx',
    'up' => $inserts,
    'down' => [
        "DELETE FROM `captcha_bypass` WHERE `email` IN ({$in_list})",
    ],
];
